class Solution {
  public int prefixConnected(String[] words, int k) {
    java.util.HashMap<String, Integer> count = new java.util.HashMap<>();
    for (String w : words) if (w.length() >= k) count.merge(w.substring(0, k), 1, Integer::sum);
    int groups = 0;
    for (int c : count.values()) if (c >= 2) groups++;
    return groups;
  }
}
